const ChatTemplatePlayground = () => {
  const [messages, setMessages] = useState([
    { id: 'user-1', role: 'user', content: 'Can you summarize the Kitchen Remodel project?' },
    { id: 'agent-1', role: 'agent', content: 'The Kitchen Remodel project is 70% complete and on budget.' },
  ])

  const handleSubmit = (prompt) => {
    setMessages((current) => [
      ...current,
      { id: `user-${Date.now()}`, role: 'user', content: prompt },
      { id: `agent-${Date.now()}`, role: 'agent', content: `Here is what I found about "${prompt}".` },
    ])
  }

  return {{component}}
}

